<?php if(!defined('SW_APP')){http_response_code(404);exit;}$rows=raffle_list();$total=0;$pending=0;$paid=0;$potential=0;$unlimited=false;foreach($rows as $r){$total+=(int)$r['income'];$pending+=(int)$r['pending_income'];$paid+=(int)$r['paid'];if($r['participation_mode']==='compartido'&&$r['close_mode']!=='capacidad')$unlimited=true;else $potential+=(int)($r['close_mode']==='capacidad'?$r['participation_limit']:$r['ticket_count'])*(int)$r['ticket_price_cents'];} ?>
<div class="page-heading"><p class="eyebrow">FINANZAS</p><h1>Ingresos</h1><p>Control de valores registrados, cobrados y pendientes.</p></div><div class="stats"><?php render_stat('Ingresos confirmados',money($total),'Boletos marcados como pagados');render_stat('Pendiente de cobro',money($pending),'Boletos registrados');render_stat('Boletos pagados',$paid);render_stat('Ingreso potencial',$unlimited?'Sin límite fijo':money($potential),'Todos los sorteos');?></div><section class="panel"><div class="section-heading"><h2>Ingresos por sorteo</h2><p>No incluye comisiones, gastos ni pasarelas de pago.</p></div><?php if(!$rows):empty_state('Sin ingresos','Los valores se calculan desde los participantes.');else:?><div class="table-wrap"><table><thead><tr><th>Sorteo</th><th>Estado</th><th>Pagados</th><th>Confirmado</th><th>Pendiente</th><th>Potencial</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['title'])?></td><td><?=chip($r['status'])?></td><td><?=(int)$r['paid']?></td><td><strong><?=money($r['income'])?></strong></td><td><?=money($r['pending_income'])?></td><td><?=$r['participation_mode']==='compartido'&&$r['close_mode']!=='capacidad'?'Sin límite fijo':money((int)($r['close_mode']==='capacidad'?$r['participation_limit']:$r['ticket_count'])*(int)$r['ticket_price_cents'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
